using System.Net;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.Extensions.Hosting;
using VIIDII.Services.Roster;
using Xunit;

namespace VIIDII.Tests;

/// <summary>
/// The import heuristics against a real registrar's spreadsheet export, rather than
/// a tidy file written to suit the parser.
/// <para>
/// <c>samples/CSC101-roster.csv</c> is generated by <c>samples/generate-csc101-roster.ps1</c>
/// and carries, on purpose, everything that has broken a column guess in practice:
/// an S/N column running sequentially past 100 with a duplicate from merged cells, a
/// gap from a filtered sheet, matric numbers in mixed case with trailing spaces, one
/// blank and one duplicate, names containing commas, names in capitals, names with
/// diacritics, one set of initials, three date formats in one column, a mail merge
/// that wrote " at " instead of "@", a truncated row, a "Total" footer, and a byte
/// order mark.
/// </para>
/// </summary>
public class Csc101RosterSampleTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly WebApplicationFactory<Program> _factory;

    public Csc101RosterSampleTests(WebApplicationFactory<Program> factory) => _factory = factory;

    private WebApplicationFactory<Program> CreateApp()
    {
        return _factory.WithWebHostBuilder(builder =>
        {
            builder.UseSetting("Database:Provider", "Sqlite");
            builder.UseSetting(
                "ConnectionStrings:DefaultConnection",
                $"Data Source=file:viidii-sample-{Guid.NewGuid():N}?mode=memory&cache=shared");
            builder.UseEnvironment("Development");
        });
    }

    /// <summary>Finds the checked-in sample from the test output directory.</summary>
    private static string SamplePath(string fileName)
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);

        while (directory is not null)
        {
            var candidate = Path.Combine(directory.FullName, "samples", fileName);

            if (File.Exists(candidate))
            {
                return candidate;
            }

            directory = directory.Parent;
        }

        throw new FileNotFoundException(
            $"Could not find samples/{fileName}. Run samples/generate-csc101-roster.ps1.");
    }

    private static string ReadSample(string fileName) => File.ReadAllText(SamplePath(fileName), Encoding.UTF8);

    [Fact]
    public void TheSampleHasTheOditiesItIsSupposedToHave()
    {
        var text = ReadSample("CSC101-roster.csv");

        // Read the bytes rather than the text: File.ReadAllText silently strips a
        // byte order mark, so asserting on the decoded text would prove nothing.
        Assert.Equal(new byte[] { 0xEF, 0xBB, 0xBF }, File.ReadAllBytes(SamplePath("CSC101-roster.csv"))[..3]);

        // Past 100, where the serial repeats because of a merged cell, and jumps at 104
        // because a row above was filtered out. Both defeat a naive serial check.
        Assert.Contains("\n99,CSC/2021/099", text.Replace("\r\n", "\n"));
        Assert.Contains("\n99,CSC/2021/100", text.Replace("\r\n", "\n"));
        Assert.Contains("\n106,CSC/2021/104", text.Replace("\r\n", "\n"));
        // A name containing a comma, which is the quoting trap.
        Assert.Contains("\"", text);

        // Diacritics and capitals.
        Assert.Contains(text, c => c > 127);

        // The summary row that is not a student.
        Assert.Contains("Total: 120 students", text);
    }

    [Fact]
    public void TheCommaSampleParsesToNineColumns()
    {
        var parsed = RosterParser.Parse(ReadSample("CSC101-roster.csv"));

        Assert.Equal(RosterSourceFormat.Csv, parsed.Format);
        Assert.Equal(9, parsed.Headers.Count);

        // The byte order mark must not end up glued to the first header name.
        Assert.Equal("S/N", parsed.Headers[0]);
    }

    [Fact]
    public void TheSemicolonSampleParsesTheSameWay()
    {
        var parsed = RosterParser.Parse(ReadSample("CSC101-roster-semicolon.csv"));

        Assert.Equal(RosterSourceFormat.Csv, parsed.Format);
        Assert.Equal(9, parsed.Headers.Count);
        Assert.Equal("S/N", parsed.Headers[0]);
        Assert.Equal("Matric No.", parsed.Headers[1]);
        Assert.Equal("Full Name", parsed.Headers[2]);
    }

    [Fact]
    public void TheMatricColumnIsChosenAsTheIdentifier()
    {
        var parsed = RosterParser.Parse(ReadSample("CSC101-roster.csv"));
        var analysis = RosterSchemaAnalyzer.Analyze(parsed.Headers, parsed.Rows);

        Assert.True(
            analysis.IdentifierColumn is not null,
            $"No identifier column was chosen. Ranked: {string.Join(", ", analysis.RankedIdentifiers.Select(c => c.Name))}");

        // S/N is the tempting wrong answer: it is perfectly populated and perfectly
        // unique, and it looks numeric, so only the serial sequence check rejects it.
        // Past 100 is where that check has to keep working.
        Assert.Equal("Matric No.", analysis.IdentifierColumn!.Name);
    }

    [Fact]
    public void TheSerialColumnIsRecognisedAsASerialAndNotAnIdentifier()
    {
        var parsed = RosterParser.Parse(ReadSample("CSC101-roster.csv"));
        var analysis = RosterSchemaAnalyzer.Analyze(parsed.Headers, parsed.Rows);

        var serial = analysis.Columns.Single(c => c.Name == "S/N");

        Assert.True(serial.LooksLikeSerialSequence, "The S/N column should be seen as a serial.");
        Assert.False(
            serial.IsLikelyIdentifier,
            "A running serial number must never be mistaken for a student identifier.");
    }

    [Fact]
    public void TheNameColumnIsChosen()
    {
        var parsed = RosterParser.Parse(ReadSample("CSC101-roster.csv"));
        var analysis = RosterSchemaAnalyzer.Analyze(parsed.Headers, parsed.Rows);

        Assert.True(
            analysis.NameColumn is not null,
            $"No name column was chosen. Ranked: {string.Join(", ", analysis.RankedNames.Select(c => c.Name))}");

        Assert.Equal("Full Name", analysis.NameColumn!.Name);
    }

    [Fact]
    public void TheAnalysisIsUsableWithoutAskingTheLecturerAnything()
    {
        var parsed = RosterParser.Parse(ReadSample("CSC101-roster.csv"));
        var analysis = RosterSchemaAnalyzer.Analyze(parsed.Headers, parsed.Rows);

        Assert.True(analysis.IsUsable);

        // The whole point of the heuristics: a lecturer uploading this file should not
        // be stopped to confirm which column is which. If it asks, they are asked
        // because the file is genuinely ambiguous, which this one should not be.
        Assert.Empty(analysis.NeedsConfirmation);
    }

    [Fact]
    public void TheEmailColumnIsNotMistakenForAnIdentifier()
    {
        var parsed = RosterParser.Parse(ReadSample("CSC101-roster.csv"));
        var analysis = RosterSchemaAnalyzer.Analyze(parsed.Headers, parsed.Rows);

        // Every populated address is unique, which on uniqueness alone would make it
        // look like a better identifier than the matric number.
        Assert.Equal("Email Address", analysis.EmailColumn?.Name);
    }

    [Fact]
    public void TheSummaryRowDoesNotStopTheIdentifierBeingFound()
    {
        var parsed = RosterParser.Parse(ReadSample("CSC101-roster.csv"));
        var analysis = RosterSchemaAnalyzer.Analyze(parsed.Headers, parsed.Rows);

        Assert.Equal("Matric No.", analysis.IdentifierColumn?.Name);
    }

    [Fact]
    public async Task TheSampleImportsThroughTheRealEndpoint()
    {
        using var app = CreateApp();
        using var client = app.CreateClient();

        var matricNo = $"LEC{Guid.NewGuid().ToString("N")[..8]}";

        Assert.Equal(
            HttpStatusCode.OK,
            (await client.PostAsJsonAsync("/api/account/register", new
            {
                name = "Dr. Amaka Obi",
                matricNo,
                password = "a-good-password"
            })).StatusCode);

        var created = await client.PostAsJsonAsync("/api/classes", new
        {
            code = "CSC101",
            name = "Introduction to Computer Science"
        });

        var classId = (await created.Content.ReadFromJsonAsync<JsonElement>())
            .GetProperty("id").GetInt32();

        var import = await client.PostAsJsonAsync($"/api/roster/classes/{classId}/import", new
        {
            content = ReadSample("CSC101-roster.csv"),
            mapping = new
            {
                identifierHeader = "Matric No.",
                nameHeader = "Full Name"
            }
        });

        Assert.Equal(HttpStatusCode.OK, import.StatusCode);

        var result = await import.Content.ReadAsStringAsync();

        using var summary = JsonDocument.Parse(result);

        var imported = summary.RootElement.GetProperty("imported").GetInt32();
        var skipped = summary.RootElement.GetProperty("skipped").GetInt32();

        // 120 students plus the summary footer. Rows with no identifier, no name or a
        // truncated line are refused on purpose rather than stored as blank people, so
        // the honest assertion is that everything is accounted for, not that all 120
        // made it.
        Assert.Equal(121, imported + skipped);
        Assert.True(imported >= 110, $"Only {imported} of 120 students were imported.");

        var stored = await client.GetFromJsonAsync<JsonElement>($"/api/roster/classes/{classId}");

        Assert.Equal(imported, stored.GetArrayLength());

        // No summary row, and no blank identifier, got in.
        // Nothing with a blank name got in either.
        Assert.DoesNotContain(
            stored.EnumerateArray(),
            e => string.IsNullOrWhiteSpace(e.GetProperty("displayName").GetString()));

        Assert.DoesNotContain(
            stored.EnumerateArray(),
            e => string.IsNullOrWhiteSpace(e.GetProperty("identifier").GetString()));

        Assert.DoesNotContain(
            stored.EnumerateArray(),
            e => (e.GetProperty("displayName").GetString() ?? string.Empty).Contains("Total", StringComparison.OrdinalIgnoreCase));
    }

    [Fact]
    public async Task StudentsOnThisListCanJoinWithTheDetailsTheyKnow()
    {
        using var app = CreateApp();
        using var lecturer = app.CreateClient();

        var matricNo = $"LEC{Guid.NewGuid().ToString("N")[..8]}";

        Assert.Equal(
            HttpStatusCode.OK,
            (await lecturer.PostAsJsonAsync("/api/account/register", new
            {
                name = "Dr. Amaka Obi",
                matricNo,
                password = "a-good-password"
            })).StatusCode);

        var created = await lecturer.PostAsJsonAsync("/api/classes", new
        {
            code = "CSC101",
            name = "Introduction to Computer Science"
        });

        var classId = (await created.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetInt32();

        await lecturer.PostAsJsonAsync($"/api/roster/classes/{classId}/import", new
        {
            content = ReadSample("CSC101-roster.csv"),
            mapping = new { identifierHeader = "Matric No.", nameHeader = "Full Name" }
        });

        var list = await lecturer.GetFromJsonAsync<JsonElement>($"/api/roster/classes/{classId}");

        // Take the rows that were awkward in the file: comma-quoted names, names in
        // capitals, and names carrying diacritics. These are the ones that decide
        // whether a real cohort can actually get in.
        var awkward = list.EnumerateArray()
            .Select(e => new
            {
                Identifier = e.GetProperty("identifier").GetString() ?? string.Empty,
                Name = e.GetProperty("displayName").GetString() ?? string.Empty
            })
            .Where(x => x.Identifier.Length > 0 && x.Name.Length > 1)
            .ToList();

        var commaNamed = awkward.First(x => x.Name.Contains(","));
        var shouted      = awkward.First(x => x.Name.Any(char.IsUpper) && x.Name == x.Name.ToUpperInvariant());
        var withDiacritic= awkward.First(x => x.Name.Any(c => c > 127));

        using var student = app.CreateClient();

        foreach (var person in new[] { commaNamed, shouted, withDiacritic })
        {
            var join = await student.PostAsJsonAsync("/api/join/CSC101", new
            {
                identifier = person.Identifier,
                name = person.Name
            });

            var body = await join.Content.ReadAsStringAsync();

            Assert.True(
                join.StatusCode == HttpStatusCode.OK,
                $"'{person.Identifier}' / '{person.Name}' -> {(int)join.StatusCode}: {body}");

            using var document = JsonDocument.Parse(body);

            Assert.Equal(
                person.Name,
                document.RootElement.GetProperty("displayName").GetString());
        }
    }
}
